package main

import (
	"bufio"
	"bytes"
	"encoding/json"
	"os"
	"testing"
)

// TestPydanticParity replays testdata/cases.json, generated by gen_cases.py
// from the original pydantic models. Each case must be rejected, fail
// conversion, or produce byte-identical current_status JSON, matching Python.
func TestPydanticParity(t *testing.T) {
	raw, err := os.ReadFile("testdata/cases.json")
	if err != nil {
		t.Fatal(err)
	}
	var fixture struct {
		SnapshotAtMs int64 `json:"snapshot_at_ms"`
		Cases        []struct {
			Name          string `json:"name"`
			Input         string `json:"input"`
			Result        string `json:"result"`
			PythonError   string `json:"python_error"`
			CurrentStatus string `json:"current_status"`
		} `json:"cases"`
	}
	if err := json.Unmarshal(raw, &fixture); err != nil {
		t.Fatal(err)
	}
	if len(fixture.Cases) == 0 {
		t.Fatal("no cases in fixture")
	}

	for _, c := range fixture.Cases {
		t.Run(c.Name, func(t *testing.T) {
			rec, err := ParseFullStatus([]byte(c.Input))
			if c.Result == "invalid" {
				if err == nil {
					t.Fatal("pydantic rejects this snapshot but ParseFullStatus accepted it")
				}
				return
			}
			if err != nil {
				t.Fatalf("pydantic accepts this snapshot but ParseFullStatus failed: %v", err)
			}

			status, err := Convert(rec, fixture.SnapshotAtMs)
			if c.Result == "error" {
				if err == nil {
					t.Fatalf("Python crashes converting this snapshot (%s) but Convert succeeded", c.PythonError)
				}
				return
			}
			if err != nil {
				t.Fatalf("Convert: %v", err)
			}

			var buf bytes.Buffer
			w := bufio.NewWriter(&buf)
			if err := WriteCurrentStatus(w, status); err != nil {
				t.Fatalf("WriteCurrentStatus: %v", err)
			}
			w.Flush()
			if got := buf.String(); got != c.CurrentStatus {
				t.Errorf("current_status mismatch\n got: %s\nwant: %s", firstDiff(got, c.CurrentStatus), firstDiff(c.CurrentStatus, got))
			}
		})
	}
}

// firstDiff returns the text around where a and b first differ.
func firstDiff(a, b string) string {
	i := 0
	for i < len(a) && i < len(b) && a[i] == b[i] {
		i++
	}
	lo, hi := max(0, i-60), min(len(a), i+60)
	return a[lo:hi]
}
